(function(root){
'use strict';
const LABELS=['','매우 불만족','불만족','만족','매우 만족'];
function shuffled(items,random=Math.random){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function selectQuestions(bank,count){const groups={};bank.forEach(q=>(groups[q.category]??=[]).push(q));const buckets=shuffled(Object.values(groups)).map(a=>shuffled(a));const selected=[];while(selected.length<Math.min(count,bank.length)){for(const b of shuffled(buckets)){if(b.length)selected.push(b.pop());if(selected.length===Math.min(count,bank.length))break;}}return shuffled(selected);}
function evaluate(q,text){const t=text.trim().replace(/\s+/g,' ');if(t.length<12)return {error:'답변이 너무 짧아 평가하기 어렵습니다. 핵심 행동이나 경험을 한 문장 이상 말씀해 주세요.'};const checks=q.criteria.map(c=>({...c,hit:new RegExp(c.pattern,'i').test(t)}));const hits=checks.filter(c=>c.hit).length;const harmful=/(보고|확인|신고)(?:를|는|도)?\s*(?:하지\s*않겠|안\s*하겠)|임의로\s*(?:판단|처리)하겠|그냥\s*(?:통과|보내주)|금품을?\s*받겠/.test(t);const structured=t.length>=55&&((t.match(/습니다|겠습니다|입니다|합니다|됩니다|했습니다|있습니다|[.!?。]/g)||[]).length>=2);let score=hits===0?1:hits===1?2:hits===2?3:structured?4:3;if(harmful)score=1;return {score,label:LABELS[score],checks,structured,harmful,good:checks.filter(c=>c.hit).map(c=>c.label),missing:checks.filter(c=>!c.hit).map(c=>c.label),text:t};}
function preferredVoice(voices){return voices.filter(v=>/^ko(?:-|_|$)/i.test(v.lang)).find(v=>/(?:InJoon|BongJin|GookMin|Hyunsu|인준|봉진|국민|현수|남성|\bmale\b)/i.test(v.name+' '+v.voiceURI))||null;}
root.InterviewCore={selectQuestions,evaluate,LABELS,preferredVoice};if(typeof module!=='undefined')module.exports=root.InterviewCore;
if(typeof document==='undefined')return;
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bank=root.QUESTION_BANK;let queue=[],index=0,results=[],active=false,answered=false,mode='practice',recognition=null,listening=false,stopping=false,speaking=false,speechToken=0,epoch=0,clock=null,elapsed=0,baseText='',interimText='',currentFollow=false;
const SR=root.SpeechRecognition||root.webkitSpeechRecognition;const STORAGE='dayun-interview-v1';
$('bankCount').textContent=bank.length;
const current=()=>queue[index];
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function controls(){const ready=active&&!answered;$('mic').disabled=!ready||!SR||speaking||stopping;$('submit').disabled=!ready||listening||stopping||speaking;$('answer').disabled=!ready||listening||stopping;$('replay').disabled=!active||listening||stopping;$('skip').disabled=!ready||listening||stopping||speaking;$('finish').disabled=!active||listening||stopping;$('start').disabled=active;$('mode').disabled=active;$('count').disabled=active;$('mic').textContent=listening?'■ 음성 답변 마치기':'● 음성 답변 시작';if(listening)$('mic').textContent='■ 음성 답변 마치기';$('session').classList.toggle('listening',listening);$('session').classList.toggle('talking',speaking);$('voicePreview').disabled=listening||stopping;}
function tick(){elapsed++;$('timer').textContent=`${String(Math.floor(elapsed/60)).padStart(2,'0')}:${String(elapsed%60).padStart(2,'0')}`;}
function startClock(){if(!clock)clock=setInterval(tick,1000);}
function stopClock(){clearInterval(clock);clock=null;}
function stopSpeech(){speechToken++;if(root.speechSynthesis)root.speechSynthesis.cancel();speaking=false;controls();}
let currentUtterance=null;
function speak(text,autoListen=false){if(listening||stopping)return;stopSpeech();const token=++speechToken;const finishSpeech=()=>{if(token!==speechToken)return;currentUtterance=null;speaking=false;controls();if(autoListen&&active&&!answered&&SR){startListening();}else status('음성 재생을 마쳤습니다.');};if(!root.speechSynthesis){status('음성 읽기를 지원하지 않습니다. 화면 질문으로 진행합니다.',true);if(autoListen)startListening();return;}const voices=root.speechSynthesis.getVoices();const selected=voices.find(v=>v.voiceURI===$('voice').value)||preferredVoice(voices)||voices.find(v=>/^ko(?:-|_|$)/i.test(v.lang));const u=new SpeechSynthesisUtterance(text);currentUtterance=u;u.lang='ko-KR';if(selected)u.voice=selected;u.rate=Number($('rate').value)||0.85;u.pitch=0.78;u.volume=1;speaking=true;controls();status('면접관이 말하고 있습니다.');$('voiceNote').textContent=selected?('재생 음성: '+selected.name+(preferredVoice([selected])?' · 남성 음성':' · 남성 음성이 없어 사용 가능한 음성으로 재생합니다.')):'기본 한국어 음성으로 재생합니다. 음성 목록을 불러오면 자동으로 갱신됩니다.';u.onend=finishSpeech;u.onerror=e=>{if(token!==speechToken)return;currentUtterance=null;speaking=false;controls();status('질문 음성 재생 실패: '+(e.error||'알 수 없음')+'. 다시 듣기 또는 음성 답변 시작을 눌러 주세요.',true);};root.speechSynthesis.speak(u);}
function loadVoices(){if(!root.speechSynthesis)return;const previous=$('voice').value;const voices=root.speechSynthesis.getVoices();const korean=voices.filter(v=>/^ko(?:-|_|$)/i.test(v.lang));$('voice').innerHTML='<option value="">자동 선택 · 남성 우선, 없으면 한국어 기본</option>'+korean.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)}</option>`).join('');if(korean.some(v=>v.voiceURI===previous))$('voice').value=previous;const chosen=korean.find(v=>v.voiceURI===previous)||preferredVoice(voices)||korean[0];$('voiceNote').textContent=chosen?`재생 음성: ${chosen.name} · ${preferredVoice([chosen])?'남성 음성':'남성 음성이 없어 기본 음성 사용'} · 낮은 톤 적용`:'음성 목록을 불러오는 중입니다. 기본 한국어 음성으로 재생합니다.';}
loadVoices();if(root.speechSynthesis)root.speechSynthesis.addEventListener('voiceschanged',loadVoices);
function resetAnswer(){stopClock();elapsed=0;$('timer').textContent='00:00';$('answer').value='';$('interim').textContent='';$('feedback').hidden=true;answered=false;currentFollow=false;}
function showQuestion(){epoch++;stopSpeech();resetAnswer();$('summary').hidden=true;const q=current();$('category').textContent=q.category;$('question').textContent=q.text;$('questionHint').textContent=mode==='exam'?'실전 모드 · 점수와 모범답안은 면접 종료 후 공개됩니다.':'결론 → 경험 또는 행동 → 다짐 순서로 답해 보세요.';$('sessionLabel').textContent=mode==='exam'?'MOCK INTERVIEW':'PRACTICE SESSION';$('progressLabel').textContent=`질문 ${index+1} / ${queue.length}`;$('progressBar').style.width=`${index/queue.length*100}%`;controls();status(SR?'준비되면 음성 답변을 시작하세요. 직접 입력해도 됩니다.':'이 브라우저는 음성 인식을 지원하지 않습니다. 직접 입력해 주세요.',!SR);if($('auto').checked)speak(q.text,true);}
let preparing=false;
$('start').onclick=async()=>{if(preparing||active)return;preparing=true;$('start').disabled=true;try{if(SR&&root.navigator?.mediaDevices?.getUserMedia){status('자동 듣기를 준비합니다. 마이크 사용 권한을 허용해 주세요.');try{const stream=await root.navigator.mediaDevices.getUserMedia({audio:true});stream.getTracks().forEach(track=>track.stop());}catch(e){status('마이크를 사용할 수 없습니다: '+(e.name||e.message)+'. 브라우저에서 마이크를 허용한 뒤 다시 시작하세요.',true);return;}}queue=selectQuestions(bank,Number($('count').value));index=0;results=[];mode=$('mode').value;active=true;$('start').textContent='면접 진행 중';loadVoices();showQuestion();$('session').scrollIntoView({behavior:'smooth',block:'start'});}finally{preparing=false;controls();}};
$('replay').onclick=()=>{if(speaking){stopSpeech();status('음성을 멈췄습니다. 답변을 시작할 수 있습니다.');}else speak(currentFollow?`${current().text} 추가 질문입니다. ${current().follow}`:current().text,true);};
$('rate').oninput=()=>{$('rateValue').textContent=`${Number($('rate').value).toFixed(2)}배`;};
$('answer').addEventListener('input',()=>{if(active&&!answered&&$('answer').value.trim())startClock();});
function startListening(){if(!active||answered||speaking||stopping||!SR)return;if(listening){stopping=true;recognition.stop();controls();status('마지막 음성을 변환하고 있습니다.');return;}stopSpeech();const rec=new SR();recognition=rec;const version=epoch;let finals='',failed=false;let startWatchdog=null;baseText=$('answer').value.trim();rec.lang='ko-KR';rec.continuous=true;rec.interimResults=true;rec.onstart=()=>{if(version!==epoch){rec.abort();return;}clearTimeout(startWatchdog);stopping=false;listening=true;startClock();controls();status('● 마이크 켜짐 · 지금 답변해 주세요. 끝나면 음성 답변 마치기를 누르세요.');};rec.onresult=e=>{if(version!==epoch)return;let temporary='';for(let i=e.resultIndex;i<e.results.length;i++){const result=e.results[i];if(result.isFinal)finals+=result[0].transcript+' ';else temporary+=result[0].transcript;}$('answer').value=[baseText,finals.trim()].filter(Boolean).join(' ');$('interim').textContent=temporary;};rec.onerror=e=>{if(version!==epoch)return;clearTimeout(startWatchdog);failed=true;stopping=false;listening=false;controls();const messages={'not-allowed':'마이크 권한 또는 브라우저의 자동 시작이 차단되었습니다. 음성 답변 시작을 직접 한 번 누르고 마이크를 허용해 주세요.','service-not-allowed':'브라우저 음성 인식 서비스 사용이 차단되었습니다. Chrome에서 다시 열어 주세요.','audio-capture':'마이크가 없습니다. 연결과 Windows 마이크 접근 권한을 확인하세요.','network':'음성 인식 서버에 연결하지 못했습니다. 인터넷 연결을 확인해 주세요.','no-speech':'음성이 감지되지 않았습니다. 음성 답변 시작을 눌러 다시 말해 주세요.','aborted':'음성 인식을 중단했습니다.'};status(messages[e.error]||'음성 인식 오류: '+e.error,true);};rec.onend=()=>{if(version!==epoch)return;clearTimeout(startWatchdog);listening=false;stopping=false;$('interim').textContent='';recognition=null;stopClock();controls();if(!failed)status('듣기가 종료되었습니다. 답변을 확인·수정한 뒤 제출하세요.');};try{stopping=true;controls();status('마이크를 자동으로 켜고 있습니다…');startWatchdog=setTimeout(()=>{if(version!==epoch||!stopping)return;failed=true;stopping=false;listening=false;rec.abort();controls();status('브라우저가 자동 듣기를 시작하지 못했습니다. 음성 답변 시작 버튼을 한 번 눌러 주세요.',true);},8000);rec.start();}catch(e){clearTimeout(startWatchdog);recognition=null;listening=false;stopping=false;controls();status('음성 인식을 시작하지 못했습니다: '+(e.name||e.message)+'. 음성 답변 시작을 직접 눌러 주세요.',true);}}
$('mic').onclick=startListening;
$('voicePreview').onclick=()=>speak('안다윤 지원자님, 지금부터 면접을 시작하겠습니다. 질문을 듣고 본인의 경험을 바탕으로 답변해 주십시오.');
$('voice').onchange=loadVoices;
function feedbackHTML(q,r){const good=r.good.length?r.good.map(x=>`<li>${esc(x)} 표현을 확인했습니다.</li>`).join(''):'<li>질문의 핵심 행동을 먼저 말해 보세요.</li>';const missing=r.missing.map(x=>`<li>${esc(x)} 내용을 보완하세요.</li>`);if(!r.structured)missing.push('<li>짧은 문장 두 개로 행동과 근거를 연결해 보세요.</li>');if(r.harmful)missing.unshift('<li>보고·확인 생략이나 임의 처리를 뜻하는 표현을 확인하세요.</li>');return `<div class="score-head"><div class="score">${esc(r.label)}<small>${r.score} / 4점</small></div><span class="score-sub">질문별 기준에 따른 자동 연습 평가</span></div><div class="feedback-grid"><div><h4>잘한 점</h4><ul>${good}</ul></div><div><h4>다듬을 점</h4><ul>${missing.join('')||'<li>핵심을 담았습니다. 모범답안을 가린 뒤 자신의 말로 다시 답해 보세요.</li>'}</ul></div></div><div class="model"><h4>짧게 기억하는 모범답안 · 2~3문장</h4><p>${esc(q.model)}</p><div class="keywords">암기 핵심어　${q.keys.map(esc).join(' → ')}</div></div><details class="rubric"><summary>평가 근거 자세히 보기</summary>${r.checks.map(c=>`<div class="criterion"><span>${esc(c.label)}</span><span>${c.hit?'핵심 표현 확인':'보완 필요'}</span></div>`).join('')}<p>3개 기준 중 0개 확인: 1점 · 1개: 2점 · 2개: 3점 · 3개와 문장 구성 확인: 4점. 명백한 절차 생략 표현은 1점입니다. 핵심 표현 일치 방식이므로 실제 의미와 다르면 참고용으로만 사용해 주세요.</p></details>`;}
function addResult(result){const slot=results.findIndex(x=>x.id===current().id);const item={id:current().id,question:currentFollow?`${current().text} / ${current().follow}`:current().text,category:current().category,elapsed,...result};if(slot>=0)results[slot]=item;else results.push(item);}
$('submit').onclick=()=>{if(!active||answered||listening||stopping||speaking)return;const q=current(),r=evaluate(q,$('answer').value);if(r.error){status(r.error,true);$('answer').focus();return;}stopClock();addResult({answer:$('answer').value,result:r,skipped:false});answered=true;controls();status(mode==='exam'?'답변을 저장했습니다. 다음 질문으로 이동합니다.':'평가가 완료되었습니다. 모범답안을 확인하고 다시 연습해 보세요.');if(mode==='exam'){next();return;}$('feedback').hidden=false;$('feedback').innerHTML=feedbackHTML(q,r)+`<div class="feedback-controls"><button id="modelVoice" class="secondary">◖ 모범답안 듣기</button><button id="retry" class="secondary">같은 질문 다시 답하기</button><button id="follow" class="secondary">꼬리질문 연습</button><button id="next" class="primary">${index===queue.length-1?'종합 결과 보기':'다음 불시 질문 →'}</button></div>`;$('modelVoice').onclick=()=>speak(q.model);$('retry').onclick=()=>{stopSpeech();epoch++;resetAnswer();$('question').textContent=q.text;controls();status('모범답안을 가렸습니다. 자신의 말로 다시 답해 보세요.');$('answer').focus();};$('follow').onclick=()=>{stopSpeech();epoch++;resetAnswer();currentFollow=true;$('question').textContent=`${q.text}\n\n추가 질문: ${q.follow}`;$('questionHint').textContent='기존 답변과 보완 내용을 함께 답변하세요. 같은 기준으로 다시 평가하고 기존 점수를 갱신합니다.';controls();if($('auto').checked)speak(q.follow,true);else status('추가 질문을 포함해 다시 답해 보세요.');};$('next').onclick=next;$('feedback').scrollIntoView({behavior:'smooth',block:'nearest'});};
function next(){stopSpeech();index++;if(index>=queue.length)finish();else showQuestion();}
$('skip').onclick=()=>{if(!active||answered||listening||stopping||speaking)return;stopClock();addResult({answer:'',result:null,skipped:true});next();};
$('finish').onclick=()=>{if(!active||listening||stopping)return;if($('answer').value.trim()&&!answered&&!confirm('아직 제출하지 않은 답변은 평가에 포함되지 않습니다. 면접을 마칠까요?'))return;finish();};
function getHistory(){try{const value=JSON.parse(localStorage.getItem(STORAGE)||'[]');return Array.isArray(value)?value:[];}catch{return [];}}
function resultDetails(items){return items.map((x,i)=>{const q=bank.find(q=>q.id===x.id);return `<details class="result-row"><summary>${i+1}. ${esc(x.question)} · ${x.skipped?'건너뜀':esc(x.result.label)+' '+x.result.score+'점'}</summary>${x.skipped?`<div class="model"><h4>모범답안</h4><p>${esc(q.model)}</p><div class="keywords">${q.keys.map(esc).join(' → ')}</div></div>`:`<p><strong>나의 답변</strong><br>${esc(x.answer)}</p>${feedbackHTML(q,x.result)}`}</details>`;}).join('');}
function finish(){if(!active)return;epoch++;stopSpeech();stopClock();active=false;answered=false;$('feedback').hidden=true;controls();$('start').textContent='새로운 면접 시작하기 ↗';const scored=results.filter(x=>!x.skipped);const average=scored.length?(scored.reduce((s,x)=>s+x.result.score,0)/scored.length).toFixed(1):'—';$('progressBar').style.width='100%';$('progressLabel').textContent='면접 종료';$('category').textContent='수고하셨습니다';$('question').textContent='한 번 더 말할수록,\n답변은 더 나다워집니다.';$('questionHint').textContent='질문별 결과를 열어 짧은 모범답안을 확인하세요.';status('연습이 끝났습니다. 새로운 회차에서는 질문이 다시 무작위로 나옵니다.');$('summary').hidden=false;$('summary').innerHTML=`<p class="eyebrow">SESSION REVIEW</p><h2>오늘의 면접 결과</h2><div class="summary-stats"><div><b>${average}</b><span>평가 평균 / 4점</span></div><div><b>${scored.length}</b><span>평가한 답변</span></div><div><b>${results.filter(x=>x.skipped).length}</b><span>건너뛴 질문</span></div></div><p class="small">질문 ${queue.length}개 중 ${results.length}개 진행 · 건너뛴 질문은 평균에서 제외합니다. 자동 점수는 연습 참고용입니다.</p>${resultDetails(results)}<button id="download" class="secondary">이번 연습 결과 내려받기</button>`;$('download').onclick=download;if(results.length){const record={date:new Date().toISOString(),mode,average,items:results};try{localStorage.setItem(STORAGE,JSON.stringify([record,...getHistory()].slice(0,20)));}catch{status('연습은 완료했지만 브라우저 저장 공간에 기록하지 못했습니다. 결과를 내려받아 주세요.',true);}}$('summary').scrollIntoView({behavior:'smooth',block:'start'});}
function download(){const lines=['안다윤의 면접실 · 연습 결과',new Date().toLocaleString('ko-KR'),'규칙 기반 자동 평가 · 실제 채용 점수가 아닙니다.',''];results.forEach((x,i)=>{const q=bank.find(q=>q.id===x.id);lines.push(`${i+1}. ${x.question}`,x.skipped?'건너뜀':`${x.result.label} ${x.result.score}/4점`,`나의 답변: ${x.answer||'—'}`,`모범답안: ${q.model}`,`핵심어: ${q.keys.join(' → ')}`,'');});const url=URL.createObjectURL(new Blob(['\ufeff'+lines.join('\n')],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='안다윤_면접연습_결과.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderHistory(){const h=getHistory();$('historyList').innerHTML=h.length?h.map(x=>`<details class="result-row"><summary>${esc(new Date(x.date).toLocaleString('ko-KR'))} · 평균 ${esc(x.average)}점</summary><p>${x.mode==='exam'?'실전':'연습'} 모드</p>${resultDetails(x.items)}</details>`).join(''):'<p class="small">아직 저장된 연습 기록이 없습니다.</p>';}
$('historyBtn').onclick=()=>{renderHistory();$('history').showModal();};$('closeHistory').onclick=()=>$('history').close();$('clearHistory').onclick=()=>{if(!confirm('이 브라우저의 모든 면접 연습 기록을 삭제할까요?'))return;try{localStorage.removeItem(STORAGE);renderHistory();}catch{alert('브라우저에서 기록을 삭제할 수 없습니다. 사이트 저장공간 설정을 확인해 주세요.');}};
root.addEventListener('beforeunload',()=>{if(recognition)recognition.abort();if(root.speechSynthesis)root.speechSynthesis.cancel();stopClock();});
if(!SR)status('음성 인식 미지원 브라우저입니다. 직접 입력으로 연습하거나 지원되는 브라우저에서 열어 주세요.',true);
})(typeof window==='undefined'?globalThis:window);
